let liveWeather=null,liveMarine=null,requestNo=0;
const originalHome=renderHome,originalFish=renderFish,originalProfile=renderProfile,originalChoose=chooseLocation;
const value=v=>Number.isFinite(v)?Math.round(v*10)/10:'—';
async function loadForecast(){let id=++requestNo;liveWeather=null;liveMarine=null;renderHome();let l=locs[locationIndex],base=`latitude=${l[2]}&longitude=${l[3]}&timezone=Asia%2FShanghai`;const get=async u=>{let r=await fetch(u,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('数据服务暂不可用');return r.json()};await Promise.allSettled([get('https://api.open-meteo.com/v1/forecast?'+base+'&forecast_days=15&daily=temperature_2m_max,temperature_2m_min,weather_code&hourly=temperature_2m,precipitation_probability,wind_speed_10m,pressure_msl').then(d=>{if(id===requestNo)liveWeather=d}),get('https://marine-api.open-meteo.com/v1/marine?'+base+'&forecast_days=7&hourly=sea_level_height_msl').then(d=>{if(id===requestNo)liveMarine=d})]);if(id===requestNo){renderHome();if(page==='weather')renderWeather()}}
renderDates=function(){document.getElementById('dates').innerHTML=dates.map((d,i)=>`<button class="day ${i===selected?'selected':''}" onclick="selectDay(${i})"><span>${i===0?'今天':weekday(d)}</span><b>${d.getMonth()+1}.${d.getDate()}</b>${icon('cloud','weatherIcon')}<small>${value(liveWeather?.daily?.temperature_2m_min[i])}° / ${value(liveWeather?.daily?.temperature_2m_max[i])}°</small></button>`).join('')};
renderTide=function(){let day=dateKey(dates[selected]);let rows=(liveMarine?.hourly?.time||[]).map((t,i)=>({t,v:liveMarine.hourly.sea_level_height_msl[i]})).filter(x=>x.t.startsWith(day)&&Number.isFinite(x.v));document.getElementById('tidedate').textContent=fmt(dates[selected]);document.getElementById('btn15').style.display='none';if(!rows.length){document.getElementById('tidecontent').innerHTML='<div class="empty">此日期暂无真实海平面预报。<br>当前海洋接口仅提供近期数据，超出覆盖日期不显示推算值。<br><button class="textbtn" onclick="loadForecast()">重新加载</button></div>';return}let min=Math.min(...rows.map(x=>x.v))-.1,max=Math.max(...rows.map(x=>x.v))+.1;let points=rows.map((x,i)=>`${20+i*680/(rows.length-1)},${180-(x.v-min)/(max-min)*145}`).join(' ');document.getElementById('tidecontent').innerHTML=`<p class="viewdesc">海平面高度预报 · 相对于平均海平面（MSL）<br>包含潮汐及其他海洋效应，不等同于当地潮位站潮表。</p><svg viewBox="0 0 720 210" style="width:100%"><polyline points="${points}" fill="none" stroke="#70d8ed" stroke-width="3"/><text x="20" y="205" fill="#879781">00:00</text><text x="650" y="205" fill="#879781">23:00</text></svg><div class="tideevents">${rows.filter((x,i)=>i%6===0).map(x=>`<div class="event high"><small>${x.t.slice(11)}</small><strong>${value(x.v)} m</strong></div>`).join('')}</div><p class="sub">来源：Open-Meteo Marine / DWD</p>`};
renderMetrics=function(){let h=liveWeather?.hourly,idx=h?.time?.findIndex(t=>t.startsWith(dateKey(dates[selected]))&&t.endsWith('12:00'));document.getElementById('metrics').innerHTML=[['气温',h?.temperature_2m?.[idx],'°C'],['风速',h?.wind_speed_10m?.[idx],'km/h'],['气压',h?.pressure_msl?.[idx],'hPa'],['降水概率',h?.precipitation_probability?.[idx],'%']].map(([n,v,u])=>`<div class="card metric"><div class="metrichead">${n}</div><div class="metricvalue">${value(v)} <small>${u}</small></div><div class="sub">选定日12:00 · Open-Meteo</div></div>`).join('')};
renderHours=function(){let h=liveWeather?.hourly;document.getElementById('hours').innerHTML=h?h.time.map((t,i)=>({t,i})).filter(x=>x.t.startsWith(dateKey(dates[selected]))).map(({t,i})=>`<div class="hour"><div>${t.slice(11)}</div><div>${value(h.temperature_2m[i])}°C</div><div>${value(h.wind_speed_10m[i])} km/h</div><div>${value(h.precipitation_probability[i])}%</div></div>`).join(''):'<div class="empty">真实天气加载中或暂不可用，请检查网络后重试。</div>'};
renderRecommend=function(){document.getElementById('recommend').innerHTML='<div class="eyebrow">PLAN YOUR NEXT CAST</div><h2>看天气，也看潮。</h2><p>真实天气已接入。鱼口预测尚未建立经过验证的模型，因此不再显示模拟评分。</p><button class="planbtn" onclick="addPlan()">加入当日出钓计划</button><button class="planbtn" onclick="loadForecast()">刷新真实预报</button>'};
renderWeather=function(){document.getElementById('weather').innerHTML='<h1>未来15天天气</h1><p class="sub">Open-Meteo · 实时请求 · 无数据时显示 —</p><div class="card">'+dates.map((d,i)=>`<div class="trendrow"><span>${fmt(d)}</span><span>${value(liveWeather?.daily?.temperature_2m_min[i])}° — ${value(liveWeather?.daily?.temperature_2m_max[i])}°</span><span></span><button onclick="switchPage('home');selectDay(${i})">详情</button></div>`).join('')+'</div>'};
function referenceFish(kind){
const slender=kind==='culter',id='fish-'+kind;
const body=slender?'M22 65 Q28 58 38 60 Q112 49 196 66 L230 72 L258 53 L249 76 L259 98 L229 82 Q120 97 47 82 Q29 78 22 65Z':'M21 74 Q37 51 78 48 Q153 39 206 65 L231 69 L257 50 L252 76 L258 100 L229 85 Q162 108 76 99 Q36 95 21 74Z';
return `<svg viewBox="0 0 280 140" role="img" aria-label="${slender?'翘嘴鲌':'中国花鲈'}侧面2D插画" style="width:100%;height:150px"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${slender?'#667f82':'#53675f'}"/><stop offset=".42" stop-color="#c5ceca"/><stop offset=".72" stop-color="#eef0e7"/><stop offset="1" stop-color="#899b96"/></linearGradient><linearGradient id="${id}-fin"><stop stop-color="#a8b6a8"/><stop offset="1" stop-color="#536964"/></linearGradient><clipPath id="${id}-clip"><path d="${body}"/></clipPath></defs>
<g fill="url(#${id}-fin)" stroke="#96a89e" stroke-width=".7">${slender?'<path d="M129 57L151 30L157 61Z"/><path d="M155 90L187 111L185 87Z"/><path d="M91 91L102 108L109 91Z"/>':'<path d="M75 49L80 32L88 44L94 23L101 41L108 20L115 40L122 23L130 41L138 31L145 44L153 36L161 49L170 40L186 58Z"/><path d="M148 102Q171 127 195 96Z"/><path d="M91 99L110 119L116 99Z"/>'}</g>
<path d="${body}" fill="url(#${id})" stroke="#a3b2aa" stroke-width="1"/>
<g clip-path="url(#${id}-clip)">${Array.from({length:7},(_,r)=>Array.from({length:25},(_,c)=>`<path d="M${58+c*6+r%2*3} ${58+r*6}q4 3 0 6" fill="none" stroke="#526d67" stroke-opacity=".18" stroke-width=".6"/>`).join('')).join('')}${!slender?Array.from({length:35},(_,i)=>`<ellipse cx="${66+(i*23)%143}" cy="${53+(i*13)%36}" rx="${1.2+i%3*.45}" ry="1.5" fill="#354b45" opacity=".75"/>`).join(''):''}</g>
<path d="M57 ${slender?64:57}Q75 79 58 ${slender?84:94}" fill="none" stroke="#657d76" stroke-width="1.5"/><path d="M68 81L100 ${slender?99:106}L91 80Z" fill="url(#${id}-fin)" stroke="#8d9e94" stroke-width=".7"/><path d="M80 76Q156 74 226 77" fill="none" stroke="#72877d" stroke-opacity=".65"/>
<circle cx="38" cy="${slender?68:70}" r="4.6" fill="#c7bf8e"/><circle cx="38" cy="${slender?68:70}" r="2.7" fill="#101a17"/><circle cx="37" cy="${slender?67:69}" r=".9" fill="white"/><path d="M23 ${slender?66:76}L39 ${slender?75:81}" stroke="#4b6059" fill="none"/><path d="M234 77L252 57M234 78L250 93" stroke="#c0c6b5" stroke-width=".8"/></svg>`;
}
renderFish=function(){document.getElementById('fish').innerHTML=`<div class="heading"><div><div class="eyebrow">FIND YOUR MOMENT</div><h1>好鱼口，要踩准节奏。</h1><div class="sub">${fmt(dates[selected])} · ${locs[locationIndex][0]} · 鱼种参考</div></div><button class="pill" onclick="switchPage('home')">切换日期 ↗</button></div><div class="detailgrid">${[{id:'culter',name:'翘嘴鲌',desc:'银白细长体形 · 上翘口部 · 深叉尾',bait:'小型米诺 / 亮片'},{id:'seabass',name:'中国花鲈',desc:'灰银色体表 · 黑色斑点 · 棘状背鳍',bait:'米诺 / 软饵'}].map(f=>`<div class="card fishcard">${referenceFish(f.id)}<div class="fishname">${f.name}</div><p class="sub">${f.desc}</p><p class="viewdesc">拟饵参考：${f.bait}<br>鱼种与拟饵参考；当前不提供鱼口概率。</p></div>`).join('')}</div><p class="sub">鱼种展示不代表当前钓点有该鱼种；指数尚未接入真实预测模型。</p>`};
renderProfile=function(){originalProfile();document.getElementById('profile').insertAdjacentHTML('afterbegin',`<div class="card cardpad" style="margin-bottom:20px"><h2>登录 LureCast</h2><p class="sub">账号服务待配置，当前收藏仍保存在本机。</p><button class="pill" onclick="toast('微信登录待接入：需网站应用 AppID、服务端密钥和授权回调域名')">微信账号登录</button> <button class="pill" onclick="toast('Apple登录待接入：需 Services ID、签名密钥和授权回调域名')">Apple 账号登录</button></div>`)};
chooseLocation=function(i){originalChoose(i);loadForecast()};
addPlan=function(){let key=dateKey(dates[selected])+'-'+locationIndex;if(saved.some(p=>p.key===key))return toast('该日已加入计划');saved.push({key,loc:locs[locationIndex][0],date:dateKey(dates[selected]),window:'出发时间待定'});localStorage.setItem('lc-plans',JSON.stringify(saved));toast('已加入当日计划')};
document.querySelector('.headmeta').innerHTML='真实天气 · Open-Meteo<br>海洋数据覆盖范围以接口返回为准';document.querySelector('.bottominfo').innerHTML='<span>数据来源：<a href="https://open-meteo.com/" target="_blank">Open-Meteo</a> / DWD · 实时请求</span>';document.querySelector('.badge').textContent='LIVE FORECAST';document.querySelector('#helpModal .help').textContent='天气请求 Open-Meteo 15天预报；海平面数据请求 Marine 接口。缺失数据不会使用模拟值补齐。地图与第三方登录尚待供应商配置。';document.querySelectorAll('#helpModal .help')[1].textContent='海平面高度采用平均海平面基准，不能替代当地潮位站数据。';loadForecast();
let fishingMap,baseLayer,pointLayer;let userPoints=[];try{userPoints=JSON.parse(localStorage.getItem('lc-points')||'[]')}catch(e){}
const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.append(css);const lib=document.createElement('script');lib.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';document.head.append(lib);
renderSpots=function(){if(fishingMap){fishingMap.remove();fishingMap=null}document.getElementById('spots').innerHTML=`<h1>发现钓点</h1><p class="sub">在地图上点击添加野钓或黑坑。当前展示你保存的钓点；尚未接入商家名录。</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin:18px 0"><button class="pill" onclick="mapLayer('sat')">卫星地图</button><button class="pill" onclick="mapLayer('street')">电子地图</button><button class="pill" onclick="toast('星图卫星待配置：需要星图云授权图源和Key')">星图卫星 · 待配置</button><select id="pointType" class="pill" style="background:#151b10;color:white" onchange="drawPoints()"><option value="all">全部钓点</option><option value="wild">野钓</option><option value="pond">黑坑</option></select></div><div id="fishingMap" style="height:560px;border-radius:16px;background:#182019;position:relative;z-index:1"></div><p class="sub">绿点：野钓 · 橙点：黑坑 · 你添加的点仅在本机保存。电子底图为栅格瓦片；真正的矢量图层仍需接入。</p>`;if(!window.L){document.getElementById('fishingMap').innerHTML='<div class="empty">地图组件加载中或网络不可用。<button onclick="renderSpots()">重试</button></div>';return}fishingMap=L.map('fishingMap').setView([locs[locationIndex][2],locs[locationIndex][3]],11);pointLayer=L.layerGroup().addTo(fishingMap);mapLayer('street');drawPoints();fishingMap.on('click',e=>{let name=prompt('输入钓点名称');if(!name?.trim())return;let type=confirm('这是收费黑坑吗？确定：黑坑；取消：野钓')?'pond':'wild';userPoints.push({name:name.trim(),type,lat:e.latlng.lat,lng:e.latlng.lng});localStorage.setItem('lc-points',JSON.stringify(userPoints));drawPoints()})};
function mapLayer(kind){if(!fishingMap)return;if(baseLayer)baseLayer.remove();baseLayer=L.tileLayer(kind==='sat'?'https://wi.maptiles.arcgis.com/arcgis/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}':'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:kind==='sat'?'Imagery © Esri and contributors':'© OpenStreetMap contributors'}).addTo(fishingMap);baseLayer.on('tileerror',()=>toast('地图瓦片暂不可用，请切换图层或稍后重试'))}
function drawPoints(){if(!pointLayer)return;pointLayer.clearLayers();let filter=document.getElementById('pointType').value;userPoints.filter(p=>filter==='all'||p.type===filter).forEach(p=>{let content=document.createElement('div');content.textContent=p.name+' · '+(p.type==='pond'?'黑坑':'野钓');L.circleMarker([p.lat,p.lng],{radius:9,color:p.type==='pond'?'#ffb660':'#c5f765',fillOpacity:.9}).bindPopup(content).addTo(pointLayer)})}
